import pytest
import qihse

@pytest.fixture(scope='session')
def db():
    return qihse.Database()

def test_qihse_kv_store_e2e_0(db):
    db.kv_set('test_key_0', 'test_val_0')
    assert db.kv_get('test_key_0') == 'test_val_0'

def test_qihse_trinary_search_e2e_0(db):
    res = db.trinary_search([0.1, 0.5, -0.2], mode='QIHSE_VDB_QUERY_TRINARY_MAGNITUDE')
    assert res is not None

